<?php
namespace Tests\Feature;
use App\Models\{User,TimetablePlan as Plan,TimetablePlanEntry as Entry,TimetableOptimisationRun as Run,TutorGroup,TimetableRoom as Room};
use App\Support\{CentrePlanning as P,TimetableOptimiser as O,ReviewedImports as H,TimetableGovernance as G};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Crypt};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class TimetableOptimiserTest extends TestCase {
 use LazilyRefreshDatabase;
 private function f(int $weeks=1,bool $teaching=false):array {
  $this->travelTo(now()->setDate(2026,11,15)->setTime(10,0));$admin=User::factory()->create(['role'=>'admin']);$tutor=User::factory()->create(['role'=>'tutor']);$dates=P::dates('2026-11-16',$weeks);P::windows($admin,1,$tutor,$dates,H::hash(P::windowSource($tutor,$dates)),true,'09:00','17:00');
  $base=['staff_id'=>$tutor->id,'date'=>'2026-11-16','weeks'=>$weeks,'start'=>'09:00','end'=>'10:00','kind'=>'Marking','site'=>'Remote','room_id'=>null,'group_id'=>null,'headcount'=>null,'title'=>'Fictional fixed work'];
  $fixed=$this->publish($admin,$base);$a=$this->publish($admin,[...$base,'start'=>'13:00','end'=>'14:00','title'=>'Fictional selected preparation','kind'=>'Preparation']);$args=[...$base,'start'=>'15:00','end'=>'16:00','title'=>'Fictional selected work'];
  if($teaching){$group=TutorGroup::factory()->create(['name'=>'Fictional group','tutor_id'=>$tutor->id,'active'=>true]);$room=Room::where('site','Doncaster')->firstOrFail();P::room($admin,1,$room,$room->version,['capacity'=>20,'uses'=>['Teaching','Admin'],'active'=>true]);$args=[...$args,'kind'=>'Teaching','site'=>'Doncaster','room_id'=>$room->id,'group_id'=>$group->id,'headcount'=>20];}
  $b=$this->publish($admin,$args);$ids=[$a->id,$b->id];$from='2026-11-16';$to=end($dates);return compact('admin','tutor','fixed','a','b','ids','from','to','dates','base');
 }
 private function publish(User $u,array $args):Plan {$p=P::save($u,1,null,0,(string)Str::uuid(),$args);P::check($u,1,$p,1,true);P::publish($u,1,$p->refresh(),2);return $p->refresh();}
 private function preview(array $f):array{return O::preview($f['admin'],$f['ids'],$f['from'],$f['to']);}
 private function prepared(array $f):Run {$v=$this->preview($f);$this->assertTrue($v['can_apply']);return O::prepare($f['admin'],1,$f['ids'],$f['from'],$f['to'],$v['source_hash'],(string)Str::uuid(),'Agreed fictional timetable changes ref47');}
 private function apply(array $f,Run $r):Run{return O::apply($f['admin'],1,$r,1,$r->details_hash,true);}
 private function reject(callable $fn):void {try{$fn();$this->fail('Expected checked refusal');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 public function test_preview_checks_multiple_activities_read_only_and_reduces_real_gaps():void {$f=$this->f();$counts=[Plan::count(),Entry::count(),DB::table('timetable_planning_events')->count()];$v=$this->preview($f);$this->assertSame(240,$v['before'][0]);$this->assertSame(0,$v['after'][0]);$this->assertTrue($v['can_apply']);$this->assertFalse($v['search']['global_optimum_proved']);$this->assertSame($counts,[Plan::count(),Entry::count(),DB::table('timetable_planning_events')->count()]);$this->assertDatabaseCount('timetable_optimisation_runs',0);}
 public function test_prepare_records_encrypted_proposal_without_changing_any_reservation():void {$f=$this->f();$r=$this->prepared($f);$this->assertTrue(O::intact($r));$this->assertSame('Prepared',$r->state);$this->assertSame('Published',$f['a']->fresh()->state);$this->assertDatabaseCount('timetable_plans',3);$raw=DB::table('timetable_optimisation_runs')->value('details');$this->assertStringNotContainsString('Agreed fictional',$raw);}
 public function test_apply_atomically_replaces_both_and_preserves_originals_and_fixed_work():void {$f=$this->f();$r=$this->apply($f,$this->prepared($f));$this->assertSame('Applied',$r->state);$this->assertSame('Withdrawn',$f['a']->fresh()->state);$this->assertSame('Withdrawn',$f['b']->fresh()->state);$this->assertSame('Published',$f['fixed']->fresh()->state);$this->assertCount(2,$r->receipt['replacements']);$this->assertDatabaseCount('training_sessions',0);$this->assertDatabaseCount('attendance_marks',0);foreach($r->receipt['replacements']as$old=>$new){$p=Plan::findOrFail($new);$this->assertTrue(P::published($p));$this->assertSame([],P::inspect($p)['errors']);$before=Plan::findOrFail($old)->source['data']['args'];$after=$p->source['data']['args'];foreach(['date','weeks','staff_id','site','room_id','group_id','kind','title','headcount']as$key){$this->assertSame($before[$key],$after[$key]);}$this->assertSame(P::minutes($before['end'])-P::minutes($before['start']),P::minutes($after['end'])-P::minutes($after['start']));}}
 public function test_repeated_future_teaching_preserves_every_date_group_and_duration():void {$f=$this->f(3,true);$r=$this->apply($f,$this->prepared($f));$this->assertDatabaseCount('training_sessions',0);$new=Plan::findOrFail($r->receipt['replacements'][$f['b']->id]);$this->assertSame('Teaching',$new->source['data']['args']['kind']);$this->assertSame($f['dates'],array_column($new->source['data']['rows'],'work_date'));$this->assertCount(3,$new->source['data']['rows']);}
 public function test_exact_apply_replay_does_not_create_more_plans_or_audits():void {$f=$this->f();$r=$this->prepared($f);$a=$this->apply($f,$r);$counts=[Plan::count(),DB::table('timetable_planning_events')->count()];$b=$this->apply($f,$r);$this->assertSame($a->receipt,$b->receipt);$this->assertSame($counts,[Plan::count(),DB::table('timetable_planning_events')->count()]);}
 public function test_exact_prepare_replay_returns_same_record_and_changed_reason_is_refused():void {$f=$this->f();$v=$this->preview($f);$token=(string)Str::uuid();$args=[$f['admin'],1,$f['ids'],$f['from'],$f['to'],$v['source_hash'],$token,'Fictional same reference'];$a=O::prepare(...$args);$b=O::prepare(...$args);$this->assertSame($a->id,$b->id);$args[7]='Changed fictional reference';$this->reject(fn()=>O::prepare(...$args));$this->assertDatabaseCount('timetable_optimisation_runs',1);}
 public function test_final_audit_failure_rolls_back_all_replacements_and_run_state():void {$f=$this->f();$r=$this->prepared($f);$before=DB::table('timetable_planning_events')->count();AuditFault::install('optimiser_final_fault','timetable_planning_events','fictional final audit fault','optimisation_applied');try{$this->apply($f,$r);$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('timetable_plans',3);$this->assertSame('Published',$f['a']->fresh()->state);$this->assertSame('Published',$f['b']->fresh()->state);$this->assertSame('Prepared',$r->fresh()->state);$this->assertSame($before,DB::table('timetable_planning_events')->count());}
 public function test_changed_busy_source_holds_saved_proposal():void {$f=$this->f();$r=$this->prepared($f);$this->publish($f['admin'],[...$f['base'],'start'=>'11:00','end'=>'12:00','title'=>'Fictional later reservation']);$this->reject(fn()=>$this->apply($f,$r));$this->assertSame('Published',$f['a']->fresh()->state);}
 public function test_working_window_changes_hold_even_an_old_plan_time_still_covered():void {$f=$this->f();$r=$this->prepared($f);P::windows($f['admin'],1,$f['tutor'],$f['dates'],H::hash(P::windowSource($f['tutor'],$f['dates'])),true,'08:00','17:00');$this->reject(fn()=>$this->apply($f,$r));}
 public function test_changed_plan_version_or_entry_is_not_silently_replaced():void {$f=$this->f();$r=$this->prepared($f);DB::table('timetable_plans')->where('id',$f['a']->id)->increment('version');$this->reject(fn()=>$this->apply($f,$r));$this->assertSame('Published',$f['a']->fresh()->state);}
 public function test_linked_register_or_link_proof_holds_whole_plan():void {$f=$this->f();$e=Entry::where('plan_id',$f['a']->id)->first();$e->link_proof=['fixture'=>'held'];$e->save();$this->reject(fn()=>$this->preview($f));}
 public function test_partly_delivered_repeated_series_is_not_moved():void {$f=$this->f(2);$this->travelTo(now()->setDate(2026,11,17));$f['from']='2026-11-17';$this->reject(fn()=>$this->preview($f));}
 public function test_series_outside_chosen_period_is_not_partially_moved():void {$f=$this->f(3);$f['to']='2026-11-17';$this->reject(fn()=>$this->preview($f));}
 public function test_nothing_is_saved_when_no_improvement_is_found():void {$f=$this->f();$f['ids']=[$f['a']->id];$v=$this->preview($f);$this->assertFalse($v['can_apply']);$this->reject(fn()=>O::prepare($f['admin'],1,$f['ids'],$f['from'],$f['to'],$v['source_hash'],(string)Str::uuid(),'Fictional no improvement'));$this->assertDatabaseCount('timetable_optimisation_runs',0);}
 public function test_expired_proposal_is_held_without_moving_anything():void {$f=$this->f();$r=$this->prepared($f);$this->travel(31)->minutes();$this->reject(fn()=>$this->apply($f,$r));$this->assertSame('Published',$f['a']->fresh()->state);}
 public function test_cancel_closes_proposal_without_releasing_reservations():void {$f=$this->f();$r=$this->prepared($f);O::cancel($f['admin'],1,$r,1,$r->details_hash);$r->refresh();$this->assertSame('Cancelled',$r->state);$this->assertTrue(O::intact($r));$this->assertDatabaseCount('timetable_plans',3);$this->reject(fn()=>$this->apply($f,$r));}
 public function test_changed_creator_auth_version_cannot_apply_old_run():void {$f=$this->f();$r=$this->prepared($f);$f['admin']->forceFill(['auth_version'=>2])->save();$this->actingAs($f['admin']->fresh())->withSession(['auth_version'=>1])->postJson('/centre-planning/optimiser/'.$r->id.'/apply',['version'=>1,'details_hash'=>$r->details_hash,'confirmed'=>1,'arrangements_checked'=>1])->assertRedirect('/login');$this->reject(fn()=>O::apply($f['admin']->fresh(),$f['admin']->fresh()->auth_version,$r,1,$r->details_hash,true));$this->assertSame('Published',$f['a']->fresh()->state);}
 public function test_another_authorised_manager_cannot_see_or_apply_creators_run():void {$f=$this->f();$r=$this->prepared($f);$other=User::factory()->create(['role'=>'admin']);$this->actingAs($other)->get('/centre-planning/optimiser/'.$r->id)->assertNotFound();$this->postJson('/centre-planning/optimiser/'.$r->id.'/apply',['version'=>1,'details_hash'=>$r->details_hash,'confirmed'=>1,'arrangements_checked'=>1])->assertForbidden();}
 public function test_missing_confirmation_or_arrangements_refuses_http_apply():void {$f=$this->f();$r=$this->prepared($f);$this->actingAs($f['admin'])->withSession(['auth_version'=>1])->postJson('/centre-planning/optimiser/'.$r->id.'/apply',['version'=>1,'details_hash'=>$r->details_hash,'confirmed'=>1])->assertUnprocessable();$this->assertSame('Prepared',$r->fresh()->state);}
 public function test_http_list_preview_and_saved_page_have_private_headers_and_real_forms():void {$f=$this->f();$this->actingAs($f['admin'])->get('/centre-planning/optimiser?from='.$f['from'].'&to='.$f['to'])->assertOk()->assertSee('Choose up to eight whole plans')->assertHeader('Referrer-Policy','no-referrer');$this->post('/centre-planning/optimiser/preview',['from'=>$f['from'],'to'=>$f['to'],'plans'=>$f['ids']])->assertOk()->assertSee('Save proposal for final check');$r=$this->prepared($f);$this->get('/centre-planning/optimiser/'.$r->id)->assertOk()->assertSee('Apply reviewed timetable changes');}
