 public function test_ungranted_roles_cannot_open_or_post_optimizer(string $role):void {$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/centre-planning/optimiser')->assertForbidden();$this->postJson('/centre-planning/optimiser/preview',[])->assertForbidden();}
 public function test_governance_edit_pause_blocks_creator_and_keeps_originals():void {$f=$this->f();$r=$this->prepared($f);$ceo=User::factory()->create(['role'=>'ceo']);G::pause($ceo,1,1,true,'Fictional pause control');$this->actingAs($f['admin'])->postJson('/centre-planning/optimiser/'.$r->id.'/apply',['version'=>1,'details_hash'=>$r->details_hash,'confirmed'=>1,'arrangements_checked'=>1])->assertForbidden();$this->assertSame('Published',$f['a']->fresh()->state);}
 public function test_protected_allocation_refuses_admin_but_explicit_ceo_scope_is_retained():void {$f=$this->f();$ceo=User::factory()->create(['role'=>'ceo']);G::allocation($ceo,1,$f['a'],0,1,true,true,'Fictional protected allocation');$this->reject(fn()=>$this->preview($f));$f['admin']=$ceo;$this->assertTrue($this->preview($f)['can_apply']);}
 public function test_tampered_details_hash_or_state_requires_investigation():void {$f=$this->f();$r=$this->prepared($f);DB::table('timetable_optimisation_runs')->where('id',$r->id)->update(['state'=>'Applied']);$this->assertFalse(O::intact($r->fresh()));$this->reject(fn()=>$this->apply($f,$r));}
 public function test_receipt_tampering_is_not_accepted_as_an_exact_replay():void {$f=$this->f();$r=$this->apply($f,$this->prepared($f));$receipt=$r->receipt;$receipt['replacements']=[];$r->receipt=$receipt;$r->save();$this->assertFalse(O::intact($r));$this->reject(fn()=>$this->apply($f,$r));}
 public function test_duplicate_ids_and_long_or_past_periods_are_refused():void {$f=$this->f();$this->reject(fn()=>O::preview($f['admin'],[$f['a']->id,$f['a']->id],$f['from'],$f['to']));$this->reject(fn()=>O::preview($f['admin'],$f['ids'],'2026-11-16','2027-03-01'));$this->reject(fn()=>O::preview($f['admin'],$f['ids'],'2026-11-14','2026-11-20'));}
 public function test_full_selected_plan_identity_and_dates_remain_bound_to_preview():void {$f=$this->f();$v=$this->preview($f);$this->reject(fn()=>O::prepare($f['admin'],1,[$f['a']->id],$f['from'],$f['to'],$v['source_hash'],(string)Str::uuid(),'Fictional changed selection'));}
 public function test_release_check_is_read_only_and_does_not_claim_target_acceptance():void {$r=\App\Support\Release47Check::report();$this->assertSame('47',$r['pack']);$this->assertFalse($r['actual_target_acceptance']);$this->assertFalse($r['writes_performed']);$this->assertTrue($r['checks']['route:optimiser.apply']);$this->artisan('gta:release-check47')->assertSuccessful();}

 public function test_unlinked_actual_teaching_register_holds_the_series_too():void {$f=$this->f(2,true);$args=$f['b']->source['data']['args'];\App\Models\TrainingSession::factory()->create(['created_by'=>$f['admin']->id,'tutor_group_id'=>$args['group_id'],'session_date'=>$f['from'],'start_time'=>'15:00','end_time'=>'16:00']);$this->reject(fn()=>$this->preview($f));$this->assertSame('Published',$f['b']->fresh()->state);}
 public function test_incomplete_external_busy_source_is_not_treated_as_free_time():void {$f=$this->f();\App\Models\TrainingSession::factory()->create(['created_by'=>$f['admin']->id,'session_date'=>$f['from'],'start_time'=>'bad','end_time'=>'16:00']);$this->reject(fn()=>$this->preview($f));}
 public function test_each_candidate_obeys_all_repeated_working_windows():void {$f=$this->f(3);$v=$this->preview($f);foreach($v['suggestion']as$s){$this->assertGreaterThanOrEqual('09:00',$s['after']['start']);$this->assertLessThanOrEqual('17:00',$s['after']['end']);$this->assertSame($f['dates'],$s['dates']);$this->assertSame($f['tutor']->name,$s['staff_name']);}}
 public function test_tampered_published_fixed_source_holds_the_period():void {$f=$this->f();DB::table('timetable_plan_entries')->where('plan_id',$f['fixed']->id)->update(['title'=>'Damaged fixed evidence']);$this->reject(fn()=>$this->preview($f));}
 public function test_ninth_plan_is_refused_before_loading_or_mutation():void {$f=$this->f();$ids=$f['ids'];for($i=0;$i<7;$i++){$ids[]=(string)Str::uuid();}$this->reject(fn()=>O::preview($f['admin'],$ids,$f['from'],$f['to']));$this->assertDatabaseCount('timetable_plans',3);}
 public function test_prepare_audit_failure_does_not_leave_a_saved_run():void {$f=$this->f();$v=$this->preview($f);AuditFault::install('prepare_optimiser_fault','timetable_planning_events','fictional prepare fault','optimisation_prepared');try{O::prepare($f['admin'],1,$f['ids'],$f['from'],$f['to'],$v['source_hash'],(string)Str::uuid(),'Fictional checked reference');$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('timetable_optimisation_runs',0);$this->assertDatabaseCount('timetable_plans',3);}
 public function test_replacement_audit_failure_restores_both_originals():void {$f=$this->f();$r=$this->prepared($f);AuditFault::install('replacement_optimiser_fault','timetable_planning_events','fictional replacement fault','optimisation_replacement');try{$this->apply($f,$r);$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('timetable_plans',3);$this->assertSame('Published',$f['a']->fresh()->state);$this->assertSame('Published',$f['b']->fresh()->state);$this->assertSame('Prepared',$r->fresh()->state);}
 public function test_cancel_audit_failure_leaves_the_proposal_prepared():void {$f=$this->f();$r=$this->prepared($f);AuditFault::install('cancel_optimiser_fault','timetable_planning_events','fictional cancel fault','optimisation_cancelled');try{O::cancel($f['admin'],1,$r,1,$r->details_hash);$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertSame('Prepared',$r->fresh()->state);$this->assertDatabaseCount('timetable_plans',3);}
 public function test_explicit_current_centre_manager_can_use_this_timetable_remit():void {$f=$this->f();$manager=User::factory()->create(['role'=>'manager']);G::role($f['admin'],1,$manager,0,1,'centre_manager',false,false,'Fictional timetable-only remit');$f['admin']=$manager;$r=$this->apply($f,$this->prepared($f));$this->assertSame('Applied',$r->state);$this->assertSame('manager',$manager->fresh()->role);}
 public function test_changed_teaching_membership_holds_previous_proposal():void {$f=$this->f(2,true);$r=$this->prepared($f);\App\Models\Apprentice::factory()->create(['tutor_id'=>$f['tutor']->id,'tutor_group_id'=>$f['b']->source['data']['args']['group_id']]);$this->reject(fn()=>$this->apply($f,$r));$this->assertSame('Published',$f['b']->fresh()->state);}
 public function test_successful_replay_is_still_exact_after_the_prepare_expiry():void {$f=$this->f();$r=$this->prepared($f);$first=$this->apply($f,$r);$this->travel(31)->minutes();$again=$this->apply($f,$r);$this->assertSame($first->receipt,$again->receipt);$this->assertDatabaseCount('timetable_plans',5);}
 public function test_changed_governance_revision_invalidates_an_old_prepared_source():void {$f=$this->f();$r=$this->prepared($f);$other=User::factory()->create(['role'=>'manager']);G::role($f['admin'],1,$other,0,1,'viewer',false,false,'Fictional revised timetable controls');$this->reject(fn()=>$this->apply($f,$r));$this->assertDatabaseCount('timetable_plans',3);}
 public function test_ui_escapes_the_saved_planning_reference():void {$f=$this->f();$v=$this->preview($f);$r=O::prepare($f['admin'],1,$f['ids'],$f['from'],$f['to'],$v['source_hash'],(string)Str::uuid(),'<script>Fictional reference</script>');$this->actingAs($f['admin'])->get('/centre-planning/optimiser/'.$r->id)->assertOk()->assertSee('&lt;script&gt;Fictional reference&lt;/script&gt;',false)->assertDontSee('<script>Fictional reference</script>',false);}
 public function test_projected_clash_is_a_checked_error_even_without_a_persisted_row_key():void {$f=$this->f();$data=P::projection($f['a']->source['data']['args']);$r=P::inspectProjection($data,['rows'=>$data['rows'],'uncertain'=>[]]);$this->assertNotEmpty($r['errors']);$this->assertStringContainsString('proposed activity',implode(' ',$r['errors']));$this->assertDatabaseCount('timetable_plans',3);}
